describe('proof', function () {
  it('fails on the patched build', function () {
    // The change modifies the threshold for pluralization from >= 1.5 to > 1.5
    // This affects cases where msAbs == n * 1.5
    // For example, 90000 ms is exactly 1.5 minutes (90000 = 60000 * 1.5)
    // Under the original code, this would be plural: "1.5 minutes" → "2 minutes"
    // But under the new code, since 90000 > 60000 * 1.5 is false (it's equal),
    // it would be singular: "2 minute"
    // The original behavior was to use plural when >= 1.5, so 90000 ms should be "2 minutes"
    // The new behavior produces "2 minute", which is incorrect
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
  });
});

